import { createServer } from 'dhcp';

const server = createServer({
    subnets: [
        {
            id: 'office',
            range: ['10.10.0.10', '10.10.0.99'],
            server: '10.10.0.1',
            netmask: '255.255.255.0',
            router: ['10.10.0.1'],
            dns: ['10.10.0.2'],
        },
        {
            id: 'lab',
            range: ['10.20.0.10', '10.20.0.99'],
            server: '10.20.0.1',
            netmask: '255.255.255.0',
            router: ['10.20.0.1'],
            dns: ['10.20.0.2'],
        },
    ],
});

server.listen();
